WITH dim_totals AS (SELECT p.segment, p.country, src.status, COUNT(*) AS num_rows, MAX(src.monthly_fee) AS max_monthly_fee FROM subscriptions src INNER JOIN customers p ON src.customer_id = p.id GROUP BY p.segment, p.country, src.status) SELECT segment, country, status, max_monthly_fee, CASE WHEN status RLIKE '^(ACTIVE|PAUSED)$' THEN 'CORE' WHEN status RLIKE '^(CANCELLED|EXPIRED)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS status_zone FROM dim_totals ORDER BY status;
